<template><div class="share-page"><main class="share-card" v-loading="loading"><div class="share-brand"><span>S</span><strong>SmartDoc 安全分享</strong></div><template v-if="document"><h1>{{document.title}}</h1><p class="updated">更新时间：{{new Date(document.updateTime).toLocaleString()}}</p><article v-html="document.content"></article></template><template v-else><h1>访问企业文档</h1><p>该链接可能设置了访问密码。</p><el-input v-model="password" show-password placeholder="输入分享密码（若无密码可留空）" @keyup.enter="openShare"/><el-button type="primary" :loading="loading" @click="openShare">打开文档</el-button></template></main></div></template>
<script setup>import{ref}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import{enterpriseApi}from'../../api/enterprise';const route=useRoute(),password=ref(''),document=ref(null),loading=ref(false);async function openShare(){loading.value=true;try{const r=await enterpriseApi.openShare(route.params.token,password.value);document.value=r.data}catch(e){ElMessage.error(e?.message||'无法打开分享文档')}finally{loading.value=false}}</script>
<style scoped>.share-page{min-height:100vh;padding:55px 20px;background:#f2eff2;color:#4e4652}.share-card{width:min(900px,100%);min-height:450px;margin:auto;padding:38px 46px;box-sizing:border-box;border:1px solid #e4dde6;border-radius:20px;background:#fff;box-shadow:0 18px 50px rgba(70,55,75,.08)}.share-brand{display:flex;align-items:center;gap:10px;color:#766783}.share-brand span{width:34px;height:34px;display:grid;place-items:center;border-radius:11px;background:#8876a0;color:#fff}.share-card h1{margin:34px 0 8px}.updated{color:#978d9a}.share-card article{margin-top:32px;padding-top:25px;border-top:1px solid #ece6ed;line-height:1.85;white-space:pre-wrap}.share-card .el-input{margin:20px 0 13px}.share-card>.el-button{width:100%}</style>
